//
//  ProjectMediaCopyInTests.swift
//  ProjectorTests
//
//  Every imported file is copied into the project's Media folder and every
//  reference is repointed at the copy. Fixtures are neutral generated bytes.
//

import XCTest
@testable import Projector

// MARK: - Copier

final class ProjectMediaCopierTests: XCTestCase {

    private var root: URL!
    private var project: URL!
    private var mediaFolder: URL!
    private var sourceFolder: URL!

    override func setUpWithError() throws {
        root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ProjectMediaCopierTests-\(UUID().uuidString)")
        // A session folder: Cut/Cut.projector with Media beside the package.
        let session = root.appendingPathComponent("Cut")
        project = session.appendingPathComponent("Cut.projector")
        mediaFolder = ProjectFolders.mediaFolder(forProjectAt: project)
        sourceFolder = root.appendingPathComponent("Elsewhere")
        try FileManager.default.createDirectory(at: project, withIntermediateDirectories: true)
        try FileManager.default.createDirectory(at: sourceFolder, withIntermediateDirectories: true)
    }

    override func tearDownWithError() throws {
        try? FileManager.default.removeItem(at: root)
    }

    private func makeSource(_ name: String, bytes: Int = 4096) throws -> URL {
        let url = sourceFolder.appendingPathComponent(name)
        try Data(repeating: 0x5A, count: bytes).write(to: url)
        return url
    }

    func testFileAlreadyInTheProjectIsNotCopied() async throws {
        try FileManager.default.createDirectory(at: mediaFolder, withIntermediateDirectories: true)
        let inside = mediaFolder.appendingPathComponent("reel.mov")
        try Data([1, 2, 3]).write(to: inside)

        let result = try await ProjectMediaCopier().copyIn(inside, projectURL: project)

        XCTAssertEqual(result, inside)
        XCTAssertEqual(try FileManager.default.contentsOfDirectory(atPath: mediaFolder.path), ["reel.mov"])
    }

    func testCopyLandsInMediaAndLeavesTheOriginalAlone() async throws {
        let source = try makeSource("take.mov")

        let copy = try await ProjectMediaCopier().copyIn(source, projectURL: project)

        XCTAssertEqual(copy.deletingLastPathComponent().standardizedFileURL.path, mediaFolder.standardizedFileURL.path)
        XCTAssertEqual(copy.lastPathComponent, "take.mov")
        XCTAssertEqual(try Data(contentsOf: copy), try Data(contentsOf: source))
        XCTAssertTrue(FileManager.default.fileExists(atPath: source.path))
    }

    /// The copy is written under a hidden temporary name and renamed, so a
    /// finished copy leaves no `.partial` behind.
    func testNoPartialFileRemainsAfterACopy() async throws {
        let source = try makeSource("take.mov")

        _ = try await ProjectMediaCopier().copyIn(source, projectURL: project)

        let names = try FileManager.default.contentsOfDirectory(atPath: mediaFolder.path)
        XCTAssertEqual(names, ["take.mov"])
        XCTAssertFalse(names.contains(where: ProjectMediaCopier.isPartialName))
    }

    func testCollidingNamesGetANumericSuffix() async throws {
        let first = try makeSource("take.mov")
        let otherFolder = root.appendingPathComponent("Other")
        try FileManager.default.createDirectory(at: otherFolder, withIntermediateDirectories: true)
        let second = otherFolder.appendingPathComponent("take.mov")
        try Data(repeating: 0x33, count: 128).write(to: second)

        let copier = ProjectMediaCopier()
        let firstCopy = try await copier.copyIn(first, projectURL: project)
        let secondCopy = try await copier.copyIn(second, projectURL: project)

        XCTAssertEqual(firstCopy.lastPathComponent, "take.mov")
        XCTAssertEqual(secondCopy.lastPathComponent, "take_1.mov")
    }

    func testUniqueDestinationSkipsTakenAndInProgressNames() throws {
        try FileManager.default.createDirectory(at: mediaFolder, withIntermediateDirectories: true)
        let source = URL(fileURLWithPath: "/elsewhere/take.mov")
        try Data().write(to: mediaFolder.appendingPathComponent("take.mov"))
        // A name claimed by a copy still being written is taken too.
        let inProgress = mediaFolder.appendingPathComponent("take_1.mov").path

        let destination = ProjectMediaCopier.uniqueDestination(
            for: source, in: mediaFolder, reserved: [inProgress]
        )

        XCTAssertEqual(destination.lastPathComponent, "take_2.mov")
    }

    func testPartialNaming() {
        let destination = URL(fileURLWithPath: "/p/Media/take.mov")
        let token = UUID()
        let partial = ProjectMediaCopier.partialURL(for: destination, token: token)
        XCTAssertEqual(partial.lastPathComponent, ".take.mov.projector-copy-\(token.uuidString).partial")
        XCTAssertTrue(ProjectMediaCopier.isPartialName(partial.lastPathComponent))
        XCTAssertFalse(ProjectMediaCopier.isPartialName("take.mov"))
        XCTAssertFalse(ProjectMediaCopier.isPartialName(".DS_Store"))
    }

    /// Only this app's exact in-progress shape counts; a user's own `.partial` file does not.
    func testIsPartialNameIsSpecific() {
        let uuid = UUID().uuidString
        XCTAssertFalse(ProjectMediaCopier.isPartialName(".x.partial"))
        XCTAssertFalse(ProjectMediaCopier.isPartialName(".x.projector-copy-notauuid.partial"))
        XCTAssertFalse(ProjectMediaCopier.isPartialName(".projector-copy-\(uuid).partial"), "no file name before the marker")
        XCTAssertFalse(ProjectMediaCopier.isPartialName("x.projector-copy-\(uuid).partial"), "not hidden")
        XCTAssertFalse(ProjectMediaCopier.isPartialName(".x.projector-copy-\(uuid)"))
        XCTAssertTrue(ProjectMediaCopier.isPartialName(".x.projector-copy-\(uuid).partial"))
    }

    func testSweepRemovesStalePartialsOnly() async throws {
        try FileManager.default.createDirectory(at: mediaFolder, withIntermediateDirectories: true)
        let stale = ProjectMediaCopier.partialURL(for: mediaFolder.appendingPathComponent("old.mov"))
        try Data([1]).write(to: stale)
        try Data([2]).write(to: mediaFolder.appendingPathComponent("keep.mov"))

        let removed = await ProjectMediaCopier().sweepStalePartials(projectURL: project)

        XCTAssertEqual(removed, 1)
        XCTAssertEqual(try FileManager.default.contentsOfDirectory(atPath: mediaFolder.path), ["keep.mov"])
    }

    /// A user's file called `.x.partial` is not ours to delete.
    func testSweepLeavesAUserPartialFileAlone() async throws {
        try FileManager.default.createDirectory(at: mediaFolder, withIntermediateDirectories: true)
        try Data([1]).write(to: mediaFolder.appendingPathComponent(".x.partial"))

        let removed = await ProjectMediaCopier().sweepStalePartials(projectURL: project)

        XCTAssertEqual(removed, 0)
        XCTAssertEqual(try FileManager.default.contentsOfDirectory(atPath: mediaFolder.path), [".x.partial"])
    }

    /// A copy cancelled before it starts must not leave a file in Media/, even
    /// though a clone is one atomic call that cannot be interrupted part-way.
    func testCancelledCopyLeavesNothingBehind() async throws {
        let source = try makeSource("take.mov")
        let copier = ProjectMediaCopier()

        let task = Task { try await copier.copyIn(source, projectURL: project) }
        task.cancel()

        do {
            _ = try await task.value
            XCTFail("Expected the copy to be cancelled")
        } catch let error as MediaCopyError {
            XCTAssertEqual(error, .cancelled)
        }
        let leftovers = (try? FileManager.default.contentsOfDirectory(atPath: mediaFolder.path)) ?? []
        XCTAssertTrue(leftovers.isEmpty)
    }

    /// `copyfile` carries the modification date across, which is what lets a copy
    /// be told from a different file of the same size.
    func testCopyKeepsTheModificationDate() async throws {
        let source = try makeSource("take.mov")
        let stamp = Date(timeIntervalSinceNow: -86_400)
        try FileManager.default.setAttributes([.modificationDate: stamp], ofItemAtPath: source.path)

        let copy = try await ProjectMediaCopier().copyIn(source, projectURL: project)

        let original = try XCTUnwrap(MediaFingerprint.of(source))
        XCTAssertTrue(original.matches(try XCTUnwrap(MediaFingerprint.of(copy))))
    }

    func testUnreadableSourceThrowsAndLeavesNothingBehind() async throws {
        let missing = sourceFolder.appendingPathComponent("gone.mov")
        do {
            _ = try await ProjectMediaCopier().copyIn(missing, projectURL: project)
            XCTFail("Expected the copy to throw")
        } catch let error as MediaCopyError {
            XCTAssertEqual(error, .sourceUnreadable)
        }
        let leftovers = (try? FileManager.default.contentsOfDirectory(atPath: mediaFolder.path)) ?? []
        XCTAssertTrue(leftovers.isEmpty)
    }
}

// MARK: - Model

final class MediaItemImportedFromTests: XCTestCase {

    private var root: URL!

    override func setUpWithError() throws {
        root = FileManager.default.temporaryDirectory
            .appendingPathComponent("MediaItemImportedFromTests-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
    }

    override func tearDownWithError() throws {
        try? FileManager.default.removeItem(at: root)
    }

    private func item(url: String = "/proj/Media/a.mov", importedFrom: String? = nil) -> MediaItem {
        var item = MediaItem(url: URL(fileURLWithPath: url), type: .video, duration: 10)
        item.importedFromURL = importedFrom.map { URL(fileURLWithPath: $0) }
        return item
    }

    func testImportedFromRoundTripsWithItsFingerprint() throws {
        var original = item(importedFrom: "/elsewhere/a.mov")
        let stamp = Date(timeIntervalSinceReferenceDate: 800_000_000.123456)
        original.importedFingerprint = MediaFingerprint(size: 42, modified: stamp)

        let decoded = try JSONDecoder().decode(MediaItem.self, from: JSONEncoder().encode(original))

        XCTAssertEqual(decoded.importedFromURL, URL(fileURLWithPath: "/elsewhere/a.mov"))
        XCTAssertEqual(decoded.importedFingerprint?.size, 42)
        XCTAssertTrue(try XCTUnwrap(decoded.importedFingerprint).matches(MediaFingerprint(size: 42, modified: stamp)))
    }

    /// Still saved under `originalPath`, so files saved by earlier builds decode.
    func testPersistedKeyIsUnchanged() throws {
        let data = try JSONEncoder().encode(item(importedFrom: "/elsewhere/a.mov"))
        let object = try XCTUnwrap(JSONSerialization.jsonObject(with: data) as? [String: Any])
        XCTAssertEqual(object["originalPath"] as? String, "/elsewhere/a.mov")
    }

    /// Projects saved before media was copied in have no such keys.
    func testLegacyProjectWithoutImportedFromDecodes() throws {
        let data = try JSONEncoder().encode(item(importedFrom: "/elsewhere/a.mov"))
        var object = try XCTUnwrap(JSONSerialization.jsonObject(with: data) as? [String: Any])
        object.removeValue(forKey: "originalPath")
        object.removeValue(forKey: "importedSize")
        object.removeValue(forKey: "importedModified")
        let legacy = try JSONSerialization.data(withJSONObject: object)

        let decoded = try JSONDecoder().decode(MediaItem.self, from: legacy)

        XCTAssertNil(decoded.importedFromURL)
        XCTAssertNil(decoded.importedFingerprint)
        XCTAssertEqual(decoded.url, URL(fileURLWithPath: "/proj/Media/a.mov"))
    }

    /// An item saved with a path but no fingerprint decodes; it just cannot claim duplicates.
    func testImportedFromWithoutFingerprintDecodes() throws {
        let data = try JSONEncoder().encode(item(importedFrom: "/elsewhere/a.mov"))
        let decoded = try JSONDecoder().decode(MediaItem.self, from: data)
        XCTAssertEqual(decoded.importedFromURL, URL(fileURLWithPath: "/elsewhere/a.mov"))
        XCTAssertNil(decoded.importedFingerprint)
    }

    @MainActor
    func testDuplicateDetectionMatchesTheSourceWhileItIsUnchanged() throws {
        let source = root.appendingPathComponent("a.mov")
        try Data(repeating: 1, count: 64).write(to: source)
        var copied = item(importedFrom: source.path)
        copied.importedFingerprint = MediaFingerprint.of(source)
        let library = ProjectMediaLibrary(items: [copied])

        XCTAssertNotNil(library.existingItem(for: URL(fileURLWithPath: "/proj/Media/a.mov")))
        XCTAssertNotNil(library.existingItem(for: source))
        XCTAssertNil(library.existingItem(for: root.appendingPathComponent("b.mov")))
    }

    /// A re-bounced mix over the same path is a new file, not the one already copied.
    @MainActor
    func testChangedFileAtTheSamePathIsNotADuplicate() throws {
        let source = root.appendingPathComponent("a.mov")
        try Data(repeating: 1, count: 64).write(to: source)
        var copied = item(importedFrom: source.path)
        copied.importedFingerprint = MediaFingerprint.of(source)
        let library = ProjectMediaLibrary(items: [copied])

        try Data(repeating: 2, count: 128).write(to: source)

        XCTAssertNil(library.existingItem(for: source))
    }

    /// Same size, different date: still not the file that was copied.
    @MainActor
    func testSameSizeButNewDateIsNotADuplicate() throws {
        let source = root.appendingPathComponent("a.mov")
        try Data(repeating: 1, count: 64).write(to: source)
        var copied = item(importedFrom: source.path)
        copied.importedFingerprint = MediaFingerprint.of(source)
        let library = ProjectMediaLibrary(items: [copied])

        try FileManager.default.setAttributes(
            [.modificationDate: Date(timeIntervalSinceNow: 3_600)], ofItemAtPath: source.path
        )

        XCTAssertNil(library.existingItem(for: source))
    }

    @MainActor
    func testRecordCopyKeepsTheFirstSourceAndTheCodecName() {
        var original = item(url: "/elsewhere/a.mov")
        original.codecName = "Apple ProRes"
        let library = ProjectMediaLibrary(items: [original])
        let copy = URL(fileURLWithPath: "/proj/Media/a.mov")
        let fingerprint = MediaFingerprint(size: 9, modified: Date(timeIntervalSinceReferenceDate: 1))

        library.recordCopy(id: original.id, importedFrom: original.url, fingerprint: fingerprint, copyURL: copy)

        let updated = library.item(withId: original.id)
        XCTAssertEqual(updated?.url, copy)
        XCTAssertEqual(updated?.importedFromURL, URL(fileURLWithPath: "/elsewhere/a.mov"))
        XCTAssertEqual(updated?.importedFingerprint, fingerprint)
        XCTAssertEqual(updated?.codecName, "Apple ProRes")
    }
}

// MARK: - Coordinator

@MainActor
final class MediaCopyInCoordinatorTests: XCTestCase {

    private var root: URL!
    private var package: URL!
    private var mediaFolder: URL!
    private var sourceFolder: URL!
    private var library: ProjectMediaLibrary!
    private var timeline: TimelineManager!
    private var document: ProjectDocument!
    private var coordinator: MediaCopyInCoordinator!

    override func setUpWithError() throws {
        root = FileManager.default.temporaryDirectory
            .appendingPathComponent("MediaCopyInCoordinatorTests-\(UUID().uuidString)")
        let session = root.appendingPathComponent("Cut")
        package = session.appendingPathComponent("Cut.projector")
        mediaFolder = ProjectFolders.mediaFolder(forProjectAt: package)
        sourceFolder = root.appendingPathComponent("Elsewhere")
        try FileManager.default.createDirectory(at: session, withIntermediateDirectories: true)
        try FileManager.default.createDirectory(at: sourceFolder, withIntermediateDirectories: true)

        library = ProjectMediaLibrary()
        timeline = TimelineManager()
        document = ProjectDocument()
        try document.save(to: package)
        coordinator = MediaCopyInCoordinator(mediaLibrary: library, timelineManager: timeline, projectDocument: document)
    }

    override func tearDownWithError() throws {
        try? FileManager.default.removeItem(at: root)
    }

    private func makeSource(_ name: String, bytes: Int = 2048) throws -> URL {
        let url = sourceFolder.appendingPathComponent(name)
        try Data(repeating: 0x42, count: bytes).write(to: url)
        return url
    }

    /// An item, a reel and a video-track audio clip all naming one file.
    private func placeVideo(at url: URL) -> MediaItem {
        let item = MediaItem(url: url, type: .video, duration: 10)
        library.load(items: [item])
        timeline.timeline.addVideoReel(
            VideoReel(mediaItemId: item.id, sourceURL: url, timelineStartFrame: 0, durationFrames: 240)
        )
        var lane = AudioLane(name: "Video audio")
        lane.addClip(AudioClip(
            mediaItemId: item.id, sourceURL: url, timelineStartFrame: 0, durationFrames: 240,
            sourceType: .videoTrack
        ))
        timeline.timeline.addAudioLane(lane)
        return item
    }

    private func assertEverythingPoints(at url: URL, file: StaticString = #filePath, line: UInt = #line) {
        XCTAssertEqual(library.items.first?.url.standardizedFileURL.path, url.standardizedFileURL.path, file: file, line: line)
        XCTAssertEqual(timeline.timeline.videoReels.first?.sourceURL.standardizedFileURL.path, url.standardizedFileURL.path, file: file, line: line)
        XCTAssertEqual(timeline.timeline.audioLanes.first?.clips.first?.sourceURL.standardizedFileURL.path, url.standardizedFileURL.path, file: file, line: line)
    }

    func testCopyRepointsItemReelAndClip() async throws {
        let source = try makeSource("take.mov")
        let item = placeVideo(at: source)

        coordinator.enqueue(item)
        await coordinator.waitUntilIdle()

        let copy = mediaFolder.appendingPathComponent("take.mov")
        XCTAssertTrue(FileManager.default.fileExists(atPath: copy.path))
        XCTAssertTrue(FileManager.default.fileExists(atPath: source.path), "The original is never touched")
        assertEverythingPoints(at: copy)
        XCTAssertEqual(library.items.first?.importedFromURL?.standardizedFileURL.path, source.standardizedFileURL.path)
        XCTAssertEqual(library.items.first?.importedFingerprint, MediaFingerprint.of(source))
        XCTAssertEqual(coordinator.status, .finished(count: 1))
    }

    /// A reel placed on the original while the copy was landing is moved by `settle`.
    func testSettleMovesAReelPlacedOnTheOriginalAfterTheCopyLanded() async throws {
        let source = try makeSource("take.mov")
        let item = MediaItem(url: source, type: .video, duration: 10)
        library.load(items: [item])

        coordinator.enqueue(item)
        await coordinator.waitUntilIdle()

        timeline.timeline.addVideoReel(
            VideoReel(mediaItemId: item.id, sourceURL: source, timelineStartFrame: 0, durationFrames: 240)
        )
        let current = coordinator.settle(itemID: item.id, placedAt: source)

        let copy = mediaFolder.appendingPathComponent("take.mov").standardizedFileURL.path
        XCTAssertEqual(current.standardizedFileURL.path, copy)
        XCTAssertEqual(timeline.timeline.videoReels.first?.sourceURL.standardizedFileURL.path, copy)
    }

    /// Placing by the item's current URL needs no repoint, and settle leaves it alone.
    func testSettleLeavesAReelAlreadyOnTheItemsURL() async throws {
        let source = try makeSource("take.mov")
        let item = placeVideo(at: source)
        coordinator.enqueue(item)
        await coordinator.waitUntilIdle()

        let current = library.item(withId: item.id)!.url
        XCTAssertEqual(coordinator.settle(itemID: item.id, placedAt: current), current)
        assertEverythingPoints(at: current)
    }

    /// Settle while the copy is still in flight does nothing: the landing repoints.
    func testSettleBeforeTheCopyLandsChangesNothing() throws {
        let source = try makeSource("take.mov")
        let item = placeVideo(at: source)

        XCTAssertEqual(coordinator.settle(itemID: item.id, placedAt: source), source)
        XCTAssertEqual(timeline.timeline.videoReels.first?.sourceURL, source)
    }

    /// Two items with one source share a single copy, and both are repointed.
    func testTwoItemsWithTheSameSourceAreBothRepointed() async throws {
        let source = try makeSource("take.mov")
        let first = MediaItem(url: source, type: .video, duration: 10)
        let second = MediaItem(url: source, type: .video, duration: 10)
        library.load(items: [first, second])
        for item in [first, second] {
            timeline.timeline.addVideoReel(
                VideoReel(mediaItemId: item.id, sourceURL: source, timelineStartFrame: 0, durationFrames: 240)
            )
        }

        coordinator.enqueue(first)
        coordinator.enqueue(second)
        await coordinator.waitUntilIdle()

        let copy = mediaFolder.appendingPathComponent("take.mov").standardizedFileURL.path
        XCTAssertEqual(library.items.map { $0.url.standardizedFileURL.path }, [copy, copy])
        XCTAssertEqual(timeline.timeline.videoReels.map { $0.sourceURL.standardizedFileURL.path }, [copy, copy])
    }

    func testDroppingTheSameOriginalAgainIsADuplicate() async throws {
        let source = try makeSource("take.mov")
        let item = placeVideo(at: source)
        coordinator.enqueue(item)
        await coordinator.waitUntilIdle()

        XCTAssertNotNil(library.existingItem(for: source))
    }

    func testFilesAlreadyInTheProjectAreNotQueued() async throws {
        try FileManager.default.createDirectory(at: mediaFolder, withIntermediateDirectories: true)
        let inside = mediaFolder.appendingPathComponent("take.mov")
        try Data([1, 2, 3]).write(to: inside)
        let item = MediaItem(url: inside, type: .video, duration: 10)
        library.load(items: [item])

        coordinator.enqueue(item)
        await coordinator.waitUntilIdle()

        XCTAssertEqual(coordinator.status, .idle)
        XCTAssertEqual(try FileManager.default.contentsOfDirectory(atPath: mediaFolder.path), ["take.mov"])
    }

    func testOpeningBringsOutsideMediaIn() async throws {
        let source = try makeSource("take.mov")
        let item = placeVideo(at: source)
        XCTAssertEqual(library.externalMediaItems(projectURL: package).count, 1)

        await coordinator.enqueueExternalMedia()
        await coordinator.waitUntilIdle()

        assertEverythingPoints(at: mediaFolder.appendingPathComponent("take.mov"))
        XCTAssertTrue(library.externalMediaItems(projectURL: package).isEmpty)
        XCTAssertEqual(library.items.first?.id, item.id)
    }

    /// The old Consolidate Media copied the library item and left the reel on the
    /// original. Reopening such a project reuses the copy instead of duplicating it.
    func testLegacyConsolidatedProjectReusesItsExistingCopy() async throws {
        let source = try makeSource("take.mov")
        try FileManager.default.createDirectory(at: mediaFolder, withIntermediateDirectories: true)
        let existingCopy = mediaFolder.appendingPathComponent("take.mov")
        try FileManager.default.copyItem(at: source, to: existingCopy)

        // The library already points at the copy; the timeline does not.
        let item = MediaItem(url: existingCopy, type: .video, duration: 10)
        library.load(items: [item])
        timeline.timeline.addVideoReel(
            VideoReel(mediaItemId: item.id, sourceURL: source, timelineStartFrame: 0, durationFrames: 240)
        )

        await coordinator.enqueueExternalMedia()
        await coordinator.waitUntilIdle()

        XCTAssertEqual(
            timeline.timeline.videoReels.first?.sourceURL.standardizedFileURL.path,
            existingCopy.standardizedFileURL.path
        )
        XCTAssertEqual(try FileManager.default.contentsOfDirectory(atPath: mediaFolder.path), ["take.mov"])
    }

    func testMissingFilesAreSkippedOnOpen() async throws {
        let gone = sourceFolder.appendingPathComponent("gone.mov")
        _ = placeVideo(at: gone)

        await coordinator.enqueueExternalMedia()
        await coordinator.waitUntilIdle()

        XCTAssertEqual(coordinator.status, .idle)
        XCTAssertEqual(library.items.first?.url, gone)
    }

    func testUnsavedProjectQueuesNothing() async throws {
        let unsaved = ProjectDocument()
        let other = MediaCopyInCoordinator(mediaLibrary: library, timelineManager: timeline, projectDocument: unsaved)
        let source = try makeSource("take.mov")

        other.enqueue(MediaItem(url: source, type: .video, duration: 10))
        await other.waitUntilIdle()

        XCTAssertEqual(other.status, .idle)
        XCTAssertFalse(FileManager.default.fileExists(atPath: mediaFolder.path))
    }

    // MARK: Optimize overlap

    func testIsCopyingWhileQueuedAndNotAfter() async throws {
        let source = try makeSource("take.mov")
        let item = placeVideo(at: source)
        XCTAssertFalse(coordinator.isCopying)

        coordinator.enqueue(item)
        XCTAssertTrue(coordinator.isCopying)

        await coordinator.waitUntilIdle()
        XCTAssertFalse(coordinator.isCopying)
    }

    func testOptimizeIsBlockedWhileCopying() async throws {
        let source = try makeSource("take.mov")
        let item = placeVideo(at: source)
        let model = OptimizationViewModel(
            service: MediaOptimizationService(), mediaLibrary: library,
            projectDocument: document, timelineManager: timeline, mediaCopyIn: coordinator
        )
        XCTAssertFalse(model.isMediaCopying)

        coordinator.enqueue(item)

        XCTAssertTrue(model.isMediaCopying)
        XCTAssertFalse(model.canOptimize)
        XCTAssertEqual(model.cannotOptimizeReason, MediaCopyInConstants.optimizeBlockedHelp)

        await coordinator.waitUntilIdle()
        XCTAssertFalse(model.isMediaCopying)
    }

    /// Move/Delete originals act on a path captured at analysis; they must never touch
    /// a file outside the project.
    func testCleanupRefusesFilesOutsideTheProject() throws {
        let model = OptimizationViewModel(
            service: MediaOptimizationService(), mediaLibrary: library,
            projectDocument: document, timelineManager: timeline
        )
        let outside = try makeSource("take.mov")
        try FileManager.default.createDirectory(at: mediaFolder, withIntermediateDirectories: true)
        let inside = mediaFolder.appendingPathComponent("take.mov")

        XCTAssertFalse(model.isInsideProject(outside, action: "move"))
        XCTAssertTrue(model.isInsideProject(inside, action: "move"))
    }

    /// The analysis saw the outside file; a copy landed before the swap. Reels are
    /// already on the copy, and the swap must still find them.
    func testOptimizeSwapFollowsTheItemsCurrentURL() async throws {
        let source = try makeSource("take.mov")
        let item = placeVideo(at: source)
        coordinator.enqueue(item)
        await coordinator.waitUntilIdle()
        let copy = mediaFolder.appendingPathComponent("take.mov")
        let optimized = root.appendingPathComponent("Cut/Optimized Media/take.mov")

        let model = OptimizationViewModel(
            service: MediaOptimizationService(), mediaLibrary: library,
            projectDocument: document, timelineManager: timeline
        )
        let analysed = OptimizedItemResult(
            mediaItemId: item.id, displayName: "take", originalSize: 100, optimizedSize: 50,
            originalURL: source, optimizedURL: optimized, isVideo: true,
            frameRate: 24, sampleRate: 48000, success: true
        )
        await model.updateReferences(from: OptimizationResult(
            itemResults: [analysed], optimizedCount: 1, skippedCount: 0,
            failedCount: 0, totalSavedBytes: 50, optimizedMediaFolder: optimized.deletingLastPathComponent()
        ))

        assertEverythingPoints(at: optimized)
        XCTAssertNotEqual(copy.path, optimized.path)
    }

    // MARK: Same path, different file

    /// A re-bounced mix over the same path is imported as a new item with a new copy;
    /// reels are never repointed at the stale one.
    func testChangedFileAtTheSamePathGetsItsOwnCopy() async throws {
        let source = try makeSource("take.mov", bytes: 2048)
        let first = placeVideo(at: source)
        coordinator.enqueue(first)
        await coordinator.waitUntilIdle()
        let firstCopy = mediaFolder.appendingPathComponent("take.mov")

        try Data(repeating: 0x43, count: 4096).write(to: source)
        XCTAssertNil(library.existingItem(for: source), "A changed file is not a duplicate")

        let second = MediaItem(url: source, type: .video, duration: 10)
        library.load(items: library.items + [second])
        timeline.timeline.addVideoReel(
            VideoReel(mediaItemId: second.id, sourceURL: source, timelineStartFrame: 240, durationFrames: 240)
        )
        coordinator.enqueue(second)
        await coordinator.waitUntilIdle()

        let secondCopy = mediaFolder.appendingPathComponent("take_1.mov")
        XCTAssertTrue(FileManager.default.fileExists(atPath: secondCopy.path))
        let reels = timeline.timeline.videoReels.sorted { $0.timelineStartFrame < $1.timelineStartFrame }
        XCTAssertEqual(reels[0].sourceURL.standardizedFileURL.path, firstCopy.standardizedFileURL.path)
        XCTAssertEqual(reels[1].sourceURL.standardizedFileURL.path, secondCopy.standardizedFileURL.path)
    }

    /// Equal size and name are not enough to reuse a copy: the date must match too.
    func testLegacyCopyWithADifferentDateIsNotReused() async throws {
        let source = try makeSource("take.mov")
        try FileManager.default.createDirectory(at: mediaFolder, withIntermediateDirectories: true)
        let lookalike = mediaFolder.appendingPathComponent("take.mov")
        try FileManager.default.copyItem(at: source, to: lookalike)
        try FileManager.default.setAttributes(
            [.modificationDate: Date(timeIntervalSinceNow: -86_400)], ofItemAtPath: lookalike.path
        )

        let item = MediaItem(url: lookalike, type: .video, duration: 10)
        library.load(items: [item])
        timeline.timeline.addVideoReel(
            VideoReel(mediaItemId: item.id, sourceURL: source, timelineStartFrame: 0, durationFrames: 240)
        )

        await coordinator.enqueueExternalMedia()
        await coordinator.waitUntilIdle()

        XCTAssertEqual(
            timeline.timeline.videoReels.first?.sourceURL.standardizedFileURL.path,
            mediaFolder.appendingPathComponent("take_1.mov").standardizedFileURL.path
        )
    }

    /// A copy that records a different origin is never bound to this source.
    func testCopyOfADifferentOriginIsNotReused() async throws {
        let source = try makeSource("take.mov")
        try FileManager.default.createDirectory(at: mediaFolder, withIntermediateDirectories: true)
        let other = mediaFolder.appendingPathComponent("take.mov")
        try FileManager.default.copyItem(at: source, to: other)

        var item = MediaItem(url: other, type: .video, duration: 10)
        item.importedFromURL = root.appendingPathComponent("Somewhere Else/take.mov")
        item.importedFingerprint = MediaFingerprint.of(source)
        library.load(items: [item])
        timeline.timeline.addVideoReel(
            VideoReel(mediaItemId: nil, sourceURL: source, timelineStartFrame: 0, durationFrames: 240)
        )

        await coordinator.enqueueExternalMedia()
        await coordinator.waitUntilIdle()

        XCTAssertEqual(
            timeline.timeline.videoReels.first?.sourceURL.standardizedFileURL.path,
            mediaFolder.appendingPathComponent("take_1.mov").standardizedFileURL.path
        )
    }

    // MARK: Opening

    /// The sweep finishes before copying starts, removes only this app's debris, and
    /// leaves a user's own `.partial` file.
    func testOpeningSweepsThenCopies() async throws {
        let source = try makeSource("take.mov")
        _ = placeVideo(at: source)
        try FileManager.default.createDirectory(at: mediaFolder, withIntermediateDirectories: true)
        let stale = ProjectMediaCopier.partialURL(for: mediaFolder.appendingPathComponent("old.mov"))
        try Data([1]).write(to: stale)
        let users = mediaFolder.appendingPathComponent(".x.partial")
        try Data([2]).write(to: users)

        await coordinator.projectOpened()
        await coordinator.waitUntilIdle()

        XCTAssertFalse(FileManager.default.fileExists(atPath: stale.path))
        XCTAssertTrue(FileManager.default.fileExists(atPath: users.path))
        assertEverythingPoints(at: mediaFolder.appendingPathComponent("take.mov"))
    }

    func testIsCopyName() {
        XCTAssertTrue(MediaCopyInCoordinator.isCopyName("take", of: "take"))
        XCTAssertTrue(MediaCopyInCoordinator.isCopyName("take_2", of: "take"))
        XCTAssertFalse(MediaCopyInCoordinator.isCopyName("take_v2", of: "take"))
        XCTAssertFalse(MediaCopyInCoordinator.isCopyName("take_", of: "take"))
        XCTAssertFalse(MediaCopyInCoordinator.isCopyName("retake", of: "take"))
    }
}
